import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    # Externally supplied probe histories can begin with forced CC rounds.
    # Track opponent behavior over the whole match and over recent windows.
    opp_c = 0
    my_c = 0
    for me, op in history:
        if op == 'C':
            opp_c += 1
        if me == 'C':
            my_c += 1
    opp_d = n - opp_c
    opp_rate = opp_c / float(n)

    # Pure unconditional cooperator: exploit after confirming.
    if n >= 14 and opp_d == 0:
        if n < 93:
            return 'D' if rng.random() < 0.92 else 'C'
        return 'D'

    # Pure or near-pure defector: defect, with rare cheap probes.
    if opp_rate <= 0.08:
        if n < 88 and rng.random() < 0.035:
            return 'C'
        return 'D'

    last_my, last_op = history[-1]

    # Recent opponent behavior.
    look = 8 if n >= 8 else n
    recent_opp_d = 0
    recent_my_d = 0
    recent_opp_c = 0
    for i in range(n - look, n):
        if history[i][1] == 'D':
            recent_opp_d += 1
        else:
            recent_opp_c += 1
        if history[i][0] == 'D':
            recent_my_d += 1

    # Endgame: against mostly cooperative opponents, exploit near the end.
    if n >= 90:
        if opp_rate >= 0.85:
            if n >= 96:
                return 'D'
            return 'D' if rng.random() < 0.7 else 'C'
        if opp_rate >= 0.55:
            return 'D' if rng.random() < 0.55 else 'C'
        return 'D'

    # Opponent just defected.
    if last_op == 'D':
        # If opponent is otherwise highly cooperative, treat isolated D as noise.
        if opp_rate >= 0.82 and recent_opp_d <= 1 and n < 88:
            return 'C'
        # If we have been locked in mutual defection, occasionally forgive.
        if last_my == 'D' and recent_my_d >= 4 and recent_opp_d >= 4:
            return 'C' if rng.random() < 0.22 else 'D'
        # Otherwise retaliate.
        return 'D' if rng.random() < 0.9 else 'C'

    # Opponent cooperated.
    # If opponent is very cooperative, cooperate but probe opportunistically.
    if opp_rate >= 0.8:
        if recent_opp_d == 0 and n >= 25 and n < 88:
            if rng.random() < 0.06:
                return 'D'
        return 'C'

    # Opponent mixed but cooperative-leaning: reciprocal cooperation.
    if opp_rate >= 0.55:
        if recent_opp_d >= 3 and recent_opp_c <= 2:
            return 'D' if rng.random() < 0.8 else 'C'
        return 'C'

    # Opponent moderately defective.
    if opp_rate >= 0.3:
        if recent_opp_d >= 3:
            return 'D'
        if last_my == 'D' and rng.random() < 0.55:
            return 'C'
        return 'D' if rng.random() < 0.45 else 'C'

    # Opponent mostly defective.
    return 'D' if rng.random() < 0.9 else 'C'
